SELECT '== one published barbershop: all meta' AS x;
SET @id := (SELECT ID FROM wp_posts WHERE post_type='barbershop' AND post_status='publish' AND post_name='portos' LIMIT 1);
SELECT ID, post_name, post_title, post_author, post_date, post_modified, LENGTH(post_content) len FROM wp_posts WHERE ID=@id;
SELECT meta_key, LEFT(REPLACE(meta_value,'\n',' '),260) v FROM wp_postmeta WHERE post_id=@id AND meta_key NOT LIKE 'essb%' AND meta_key NOT LIKE 'wbounce%' AND meta_key NOT LIKE 'yt%' AND meta_key NOT LIKE 'eg_%' ORDER BY meta_key;
SELECT '== terms of it' AS x;
SELECT tt.taxonomy, t.term_id, t.name, t.slug, tt.parent FROM wp_term_relationships tr JOIN wp_term_taxonomy tt ON tt.term_taxonomy_id=tr.term_taxonomy_id JOIN wp_terms t ON t.term_id=tt.term_id WHERE tr.object_id=@id;
SELECT '== locations tree sample' AS x;
SELECT t.term_id, t.name, t.slug, tt.parent, tt.count FROM wp_term_taxonomy tt JOIN wp_terms t ON t.term_id=tt.term_id WHERE tt.taxonomy='locations' ORDER BY tt.parent, t.slug LIMIT 30;
SELECT '== metros sample' AS x;
SELECT t.term_id, t.name, t.slug, tt.parent, tt.count FROM wp_term_taxonomy tt JOIN wp_terms t ON t.term_id=tt.term_id WHERE tt.taxonomy='metros' ORDER BY tt.count DESC LIMIT 10;
SELECT '== termmeta keys' AS x;
SELECT meta_key, COUNT(*) FROM wp_termmeta GROUP BY meta_key;
SELECT '== post (article) meta keys' AS x;
SELECT pm.meta_key, COUNT(*) c FROM wp_postmeta pm JOIN wp_posts p ON p.ID=pm.post_id WHERE p.post_type IN ('post','page') AND pm.meta_key NOT LIKE 'essb%' GROUP BY pm.meta_key ORDER BY c DESC LIMIT 30;
SELECT '== attachment sample' AS x;
SELECT ID, post_parent, guid, post_mime_type FROM wp_posts WHERE post_type='attachment' ORDER BY ID DESC LIMIT 3;
SELECT meta_key, LEFT(meta_value,200) FROM wp_postmeta WHERE post_id=(SELECT MAX(ID) FROM wp_posts WHERE post_type='attachment') ;
SELECT '== reviews (comments on barbershops)' AS x;
SELECT c.comment_ID, c.comment_post_ID, p.post_type, c.comment_approved, LEFT(c.comment_content,80), (SELECT GROUP_CONCAT(meta_key,'=',meta_value) FROM wp_commentmeta cm WHERE cm.comment_id=c.comment_ID) meta FROM wp_comments c JOIN wp_posts p ON p.ID=c.comment_post_ID ORDER BY c.comment_ID DESC LIMIT 8;
SELECT p.post_type, COUNT(*) FROM wp_comments c JOIN wp_posts p ON p.ID=c.comment_post_ID GROUP BY p.post_type;
SELECT '== favorites / claims in usermeta' AS x;
SELECT meta_key, COUNT(*) c FROM wp_usermeta GROUP BY meta_key ORDER BY c DESC LIMIT 40;
SELECT '== school & vacancy meta' AS x;
SELECT pm.meta_key, COUNT(*) c FROM wp_postmeta pm JOIN wp_posts p ON p.ID=pm.post_id WHERE p.post_type IN ('bs_school','bs_vacancy') GROUP BY pm.meta_key ORDER BY c DESC LIMIT 30;
SELECT '== chain/collection termmeta & content' AS x;
SELECT t.name, t.slug, LEFT(tt.description,150) FROM wp_term_taxonomy tt JOIN wp_terms t ON t.term_id=tt.term_id WHERE tt.taxonomy IN ('chain','collection') LIMIT 6;
SELECT '== listing_featured & closed flags' AS x;
SELECT meta_key, meta_value, COUNT(*) FROM wp_postmeta WHERE meta_key IN ('listing_featured','listing_strizh','listing_onl','listing_school') GROUP BY meta_key, meta_value;
